#sleep 3
!x=int; echo bb-\$x-ok
#wait bb-int-ok
!sleep 20; x=slept; echo bb-\$x
#sleep 3
#intr
#sleep 1
!echo bb-after-intr-\$?
#wait bb-after-intr-[0-9]
!exit
#sleep 2
echo after-bb-int \$?"
